int process_diag_message(struct sk_buff *skb, struct nlmsghdr *nlh) {
    struct sock_diag_handler *handler;

    if (nlh->nlmsg_len < NLMSG_HDRLEN) {
        return -EINVAL;
    }

    handler = sock_diag_get_handler(nlh);
    if (!handler) {
        return -ENOENT;
    }

    if (try_module_get(handler->owner)) {
        int err = handler->dump(skb, nlh);
        module_put(handler->owner);
        return err;
    }

    return -EBUSY;
}

int process_socket_diag_message(struct sk_buff *skb, struct nlmsghdr *nlh)
{
    int ret = -EINVAL;
    struct sock_diag_handler *handler;

    if (nlh->nlmsg_len < NLMSG_HDRLEN)
        return ret;

    handler = sock_diag_get_handler(nlh);
    if (!handler)
        return ret;

    if (handler->dump) {
        handler->lock ? handler->lock(handler) : 0;
        ret = handler->dump(skb, nlh);
        handler->unlock ? handler->unlock(handler) : 0;
    }

    return ret;
}

int process_sock_diag_message(struct sk_buff *skb, struct nlmsghdr *nlh)
{
    int ret = -EINVAL;
    struct sock_diag_handler *handler;

    if (nlh->nlmsg_len < sizeof(*nlh))
        return ret;

    handler = sock_diag_get_handler(nlh->nlmsg_type);
    if (!handler)
        return ret;

    if (!try_module_get(handler->owner))
        return -EBUSY;

    ret = handler->dump(skb, nlh);

    module_put(handler->owner);
    return ret;
}

int process_diag_message(struct sk_buff *skb, struct nlmsghdr *nlh) {
    int ret = -EINVAL;

    if (nlh->nlmsg_len < sizeof(*nlh))
        return ret;

    struct sock_diag_handler *handler = sock_diag_get_handler(nlh->nlmsg_family);
    if (!handler)
        return ret;

    sock_diag_lock_handler(handler);
    if (handler->dump && !handler->destroy) {
        ret = handler->dump(skb, nlh);
    } else {
        ret = -EOPNOTSUPP;
    }
    sock_diag_unlock_handler(handler);

    return ret;
}

int process_diag_message(struct sk_buff *skb, struct nlmsghdr *nlh) {
    int ret = -EINVAL;

    if (nlh->nlmsg_len < sizeof(*nlh)) {
        return ret;
    }

    struct sock_diag_handler *handler = get_diag_handler(nlh->nlmsg_type);
    if (!handler) {
        return -ENOPROTOOPT;
    }

    rtnl_lock();
    if (handler->dump) {
        ret = handler->dump(skb, nlh);
    } else {
        ret = -EINVAL;
    }
    rtnl_unlock();

    return ret;
}
